import{_ as o,l,o as e,c as n,v as t,p as s,x as r,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"微观结构不变量","description":"","frontmatter":{"title":"微观结构不变量","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/microstructure-invariance.md","filePath":"quant/microstructure-invariance.md","lastUpdated":1789023840000}'),h={name:"quant/microstructure-invariance.md"};function u(m,a,E,_,b,B){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="微观结构不变量" tabindex="-1">微观结构不变量 <a class="header-anchor" href="#微观结构不变量" aria-label="Permalink to &quot;微观结构不变量&quot;">​</a></h1><div class="epigraph"><p>不同股票的价格、股数、波动看起来天差地别，但用「生意量」重新标度之后，买卖价差、深度和交易频率会落在相近的关系上。不变量是跨资产的缩放律，不是又一个 lambda 估计窗口。</p><footer>—— Kyle and Obizhaeva, Market Microstructure Invariance: Empirical and Theoretical Foundations, Econometrica, 2016</footer></div><p><a href="/quant/vol-liquidity-feedback">波动–流动性反馈</a>描述同一资产上流动性与波动如何互推。缺口是跨资产：为何大盘活跃股与小盘冷清股的微观结构数字，在适当标度后可以比较？Kyle 与 Obizhaeva（2016）提出微观结构不变量：用成交金额与收益波动合成的生意量（business time）来缩放订单大小、到达率与成本。本课写缩放的含义，不重推单期 Kyle \\(\\lambda\\) 的正态公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>直接比较两只股票的报价价差或「每股冲击」没有单位。一只股价 \\(10\\)、一只 \\(200\\)，tick、手数、波动都不同。不变量猜想：存在一个以「赌的风险转移量」衡量的时钟，在这个时钟上，一次「典型赌注」的成本、大小与频率满足与品种无关的关系。于是执行成本、最优切片、甚至压力期的脆弱性，可以用生意量在品种之间搬运，而不必每只股票估一套结构参数。</p><p>这与 Amihud ILLIQ、经验 \\(\\lambda\\) 的截面比较相关，但更强：它给出指数形式的缩放，而不只是「不流动的股票冲击大」。</p><h3 id="生意时间而不是日历时间" tabindex="-1">生意时间而不是日历时间 <a class="header-anchor" href="#生意时间而不是日历时间" aria-label="Permalink to &quot;生意时间而不是日历时间&quot;">​</a></h3><p>活跃股票的一天包含更多独立的微观赌注，冷清股票的一天更短。日历 VR、日历波动因此不可比。事件时间课已经用成交笔数近似交易时钟；不变量用风险转移量，把波动也乘进去：同样一笔成交，在高波动品种上是更大的赌注。</p><p><span class="marginnote">不变量是假设加校准，不是从 Kyle 1985 单期均衡直接推出来的定理。2016 年文章给出理论动机与实证，阅读时把「不变」当成近似缩放，而不是自然常数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记美元成交速度与收益方差，合成业务时间强度 \\(I\\)。订单的「赌注规模」用份额相对 \\(I\\) 的幂来缩放；成本（价差、冲击）随 \\(I\\) 以特定指数下降。实证：在截面上把对数成本、对数尺寸对 \\(\\log I\\) 回归，看斜率是否接近理论指数，残差是否还有行业结构。应用：把一只股票上估的冲击函数，按 \\(I\\) 的比映射到另一只，作为执行先验。</p><p>与宏观形状：不同品种的 \\(q(\\delta)\\) 在 tick 空间里不可比；按不变量标度后的「深度相对典型赌注」才可画在一起。pro-rata 期货与 FIFO 股票仍可能落在不同族——规则是缩放解释不了的残差。</p>',12)),(e(),s(p,null,{default:r(()=>[d(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20LR%0A%20%20Px%5B%22%E4%BB%B7%E6%A0%BC%20%2F%20%E8%82%A1%E6%95%B0%20%2F%20%CF%83%22%5D%20--%3E%20I%5B%22%E7%94%9F%E6%84%8F%E9%87%8F%20I%22%5D%0A%20%20I%20--%3E%20Cost%5B%22%E6%88%90%E6%9C%AC%E4%B8%8E%E5%B0%BA%E5%AF%B8%E7%9A%84%E7%BC%A9%E6%94%BE%22%5D%0A%20%20I%20--%3E%20Clock%5B%22%E4%B8%9A%E5%8A%A1%E6%97%B6%E9%92%9F%E4%B8%8A%E7%9A%84%E5%88%B0%E8%BE%BE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>经济内容是：做市与知情交易的约束（资本、注意力、被捡）按风险单位计价，而不是按股数计价。Kyle 的 \\(\\lambda\\) 本身有单位；不变量试图给出 \\(\\lambda\\) 如何随品种的 \\(I\\) 变，使「深度」在风险空间可比。压力期 \\(I\\) 跳变（成交金额崩、波动爆）等于业务时钟加速或赌注变大，成本沿缩放律上移——与螺旋同方向，但给出数量级。</p><p>对速度竞赛：期权 \\(s\\) 的美元价值随品种变，竞赛投入应按 \\(I\\) 缩放。在极小的冷清股上，军备竞赛可能根本不值得，HFT 做市也不进入，义务与专家更重要。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>指数对样本（美股、是否含 tick 约束、是否含开收盘）敏感。涨跌停、最小价差钉住会打断缩放。加密与外汇的 \\(I\\) 定义（以何货币、何波动）不唯一。把不变量当精确执行公式，会忽略当天的形状波动与新闻。它是先验与截面比较工具，不是替代 Hasbrouck 永久影响的估计。</p><p><span class="marginnote">不要用「不变量」去宣称所有市场微观结构相同。它只说：在业务时钟上，某些矩的缩放可以近似普适；规则与碎片化仍在残差里。</span></p><p>下一课收束速度本身：缩放律告诉你成本的数量级，不告诉你绝对变快与相对延迟哪一个在改质量。政策变量仍是协议如何处理先到者通吃。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Kyle–Obizhaeva 不变量用生意量把成本、尺寸、频率跨品种缩放。</li><li>比较微观结构应在业务时钟上，而不是日历或每股上。</li><li>规则、tick、涨跌停是缩放律的残差来源。</li><li>出处：Kyle and Obizhaeva, <em>Econometrica</em>, 2016。</li></ul>',9))])}const I=o(h,[["render",u]]);export{f as __pageData,I as default};
